<?php

declare(strict_types=1);

namespace Architex\Platform\Documents;

use Architex\Platform\Audit\AuditService;
use Architex\Platform\Identity\Identifier;
use Architex\Platform\Project\ProjectContext;
use Architex\Platform\Project\ProjectPhase;
use Architex\Platform\Records\ProjectRecordService;
use PDO;
use PDOException;
use Throwable;

final readonly class DocumentTransmittalService
{
    private const PURPOSES=['for_review','for_information','for_municipal_submission','for_tender','for_construction','as_built','closeout'];
    public function __construct(private PDO$pdo){}

    /** @param array<string,mixed> $input @return array<string,mixed> */
    public function create(string$o,string$u,string$r,array$input):array
    {
        $this->writer($o,$u,$r);$projectId=$this->id($input['projectId']??null,'transmittal_project_required');$this->project($o,$projectId);$code=$this->text($input['code']??null,80,'transmittal_code_required');$title=$this->text($input['title']??null,220,'transmittal_title_required');$purpose=$this->choice($input['purpose']??null,self::PURPOSES,'transmittal_purpose_invalid');$roles=$this->roles($input['recipientRoles']??null);$revisions=$input['revisionIds']??null;if(!is_array($revisions)||$revisions===[]||count($revisions)>100)throw new DocumentException('transmittal_revisions_required');$revisionIds=[];foreach($revisions as$value){$id=$this->id($value,'transmittal_revision_invalid');$revisionIds[$id]=true;}$items=$this->revisionItems($o,$projectId,array_keys($revisionIds),$purpose);$notes=$this->optional($input['notes']??'',12000,'transmittal_notes_invalid');$id=Identifier::generate();
        $this->pdo->beginTransaction();try{$this->pdo->prepare("INSERT INTO document_transmittals(id,organisation_id,project_id,code,title,purpose,recipient_roles,notes,status,created_by) VALUES(UNHEX(:id),UNHEX(:o),UNHEX(:p),:code,:title,:purpose,:roles,:notes,'draft',UNHEX(:u))")->execute(['id'=>$id,'o'=>$o,'p'=>$projectId,'code'=>$code,'title'=>$title,'purpose'=>$purpose,'roles'=>$this->json($roles),'notes'=>$notes,'u'=>$u]);$statement=$this->pdo->prepare('INSERT INTO document_transmittal_items(transmittal_id,revision_id,item_order) VALUES(UNHEX(:transmittal),UNHEX(:revision),:position)');foreach($items as$position=>$item)$statement->execute(['transmittal'=>$id,'revision'=>$item['revisionId'],'position'=>$position+1]);(new AuditService($this->pdo))->append($o,$u,'document_transmittal.created','document_transmittal',$id,['projectId'=>$projectId,'code'=>$code,'purpose'=>$purpose,'revisionIds'=>array_column($items,'revisionId'),'recipientRoles'=>$roles]);$this->pdo->commit();}catch(PDOException$e){if($this->pdo->inTransaction())$this->pdo->rollBack();if((string)$e->getCode()==='23000')throw new DocumentException('transmittal_code_exists');throw$e;}catch(Throwable$e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw$e;}return$this->get($o,$u,$id);
    }

    /** @return array<string,mixed> */
    public function issue(string$o,string$u,string$r,string$id,bool$confirmed,string$reason):array
    {
        $this->writer($o,$u,$r);if(!$confirmed)throw new DocumentException('transmittal_issue_confirmation_required');$reason=$this->text($reason,500,'transmittal_issue_reason_required');$current=$this->get($o,$u,$id);if($current['status']!=='draft')throw new DocumentException('transmittal_not_draft');$snapshot=['transmittalId'=>$id,'projectId'=>$current['projectId'],'code'=>$current['code'],'title'=>$current['title'],'purpose'=>$current['purpose'],'recipientRoles'=>$current['recipientRoles'],'notes'=>$current['notes'],'items'=>$current['items'],'issueReason'=>$reason,'issuedBy'=>$u,'delivery'=>['architexInboxCreated'=>true,'externalEmailSent'=>false,'externalDeliveryClaimed'=>false]];$json=$this->json($snapshot);$sha=hash('sha256',$json);
        $this->pdo->beginTransaction();try{$statement=$this->pdo->prepare("UPDATE document_transmittals SET status='issued',issue_reason=:reason,snapshot_payload=:snapshot,snapshot_sha256=:sha,issued_by=UNHEX(:u),issued_at=UTC_TIMESTAMP(6) WHERE id=UNHEX(:id) AND organisation_id=UNHEX(:o) AND status='draft'");$statement->execute(['reason'=>$reason,'snapshot'=>$json,'sha'=>$sha,'u'=>$u,'id'=>$id,'o'=>$o]);if($statement->rowCount()!==1)throw new DocumentException('transmittal_not_draft');$recordId=(new ProjectRecordService($this->pdo))->issue(new ProjectContext($o,$u,$current['projectId'],$r),ProjectPhase::from($current['phase']),'documents','document_transmittal',$current['code'].' '.$current['title'],'issued',['transmittalId'=>$id,'snapshotSha256'=>$sha,'purpose'=>$current['purpose'],'recipientRoles'=>$current['recipientRoles'],'revisionIds'=>array_column($current['items'],'revisionId'),'externalDeliveryClaimed'=>false],['required'=>true,'approvedBy'=>$u,'humanApprovalConfirmed'=>true]);$this->pdo->prepare('UPDATE document_transmittals SET project_record_id=UNHEX(:record) WHERE id=UNHEX(:id)')->execute(['record'=>$recordId,'id'=>$id]);foreach($current['recipientRoles']as$role)$this->inbox($o,$current['projectId'],$role,$id,$current['code'],$current['title'],$sha);(new AuditService($this->pdo))->append($o,$u,'document_transmittal.issued','document_transmittal',$id,['projectId'=>$current['projectId'],'snapshotSha256'=>$sha,'reason'=>$reason,'recipientRoles'=>$current['recipientRoles'],'externalDeliveryClaimed'=>false]);$this->pdo->commit();}catch(Throwable$e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw$e;}return$this->get($o,$u,$id);
    }

    /** @return array<string,mixed> */
    public function get(string$o,string$u,string$id):array
    {
        $this->member($o,$u);$id=$this->id($id,'transmittal_not_found');$s=$this->pdo->prepare("SELECT LOWER(HEX(t.id)) id,LOWER(HEX(t.project_id)) project_id,t.code,t.title,t.purpose,t.recipient_roles,t.notes,t.status,t.issue_reason,t.snapshot_payload,t.snapshot_sha256,LOWER(HEX(t.project_record_id)) project_record_id,LOWER(HEX(t.created_by)) created_by,LOWER(HEX(t.issued_by)) issued_by,DATE_FORMAT(t.issued_at,'%Y-%m-%dT%H:%i:%s.%fZ') issued_at,DATE_FORMAT(t.created_at,'%Y-%m-%dT%H:%i:%s.%fZ') created_at,p.current_phase phase FROM document_transmittals t JOIN projects p ON p.id=t.project_id AND p.organisation_id=t.organisation_id WHERE t.id=UNHEX(:id) AND t.organisation_id=UNHEX(:o)");$s->execute(['id'=>$id,'o'=>$o]);$row=$s->fetch();if(!is_array($row))throw new DocumentException('transmittal_not_found');$items=$this->storedItems($o,$id);$roles=json_decode((string)$row['recipient_roles'],true,32,JSON_THROW_ON_ERROR);$snapshot=null;if(is_string($row['snapshot_payload'])){$snapshot=json_decode($row['snapshot_payload'],true,64,JSON_THROW_ON_ERROR);if(!hash_equals((string)$row['snapshot_sha256'],hash('sha256',$this->json($snapshot))))throw new DocumentException('transmittal_integrity_failed');}return['id'=>$row['id'],'projectId'=>$row['project_id'],'code'=>$row['code'],'title'=>$row['title'],'purpose'=>$row['purpose'],'recipientRoles'=>$roles,'notes'=>$row['notes'],'status'=>$row['status'],'items'=>$items,'issueReason'=>$row['issue_reason'],'snapshot'=>$snapshot,'snapshotSha256'=>$row['snapshot_sha256'],'projectRecordId'=>$row['project_record_id'],'createdBy'=>$row['created_by'],'issuedBy'=>$row['issued_by'],'issuedAt'=>$row['issued_at'],'createdAt'=>$row['created_at'],'phase'=>$row['phase'],'externalDeliveryClaimed'=>false];
    }

    /** @return list<array<string,mixed>> */public function list(string$o,string$u,string$p):array{$this->member($o,$u);$this->project($o,$p);$s=$this->pdo->prepare('SELECT LOWER(HEX(id)) FROM document_transmittals WHERE organisation_id=UNHEX(:o) AND project_id=UNHEX(:p) ORDER BY created_at DESC,id DESC');$s->execute(['o'=>$o,'p'=>$p]);return array_map(fn(string$id):array=>$this->get($o,$u,$id),$s->fetchAll(PDO::FETCH_COLUMN));}
    /** @param list<string> $ids @return list<array<string,mixed>> */private function revisionItems(string$o,string$p,array$ids,string$purpose):array{$out=[];foreach($ids as$id){$s=$this->pdo->prepare("SELECT LOWER(HEX(r.id)) revisionId,LOWER(HEX(r.document_id)) documentId,r.revision_code revisionCode,r.status,r.issue_purpose issuePurpose,r.audit_hash documentAuditHash,d.title,d.document_type documentType,d.discipline FROM document_revisions r JOIN controlled_documents d ON d.id=r.document_id AND d.organisation_id=r.organisation_id WHERE r.id=UNHEX(:id) AND r.organisation_id=UNHEX(:o) AND r.project_id=UNHEX(:p)");$s->execute(['id'=>$id,'o'=>$o,'p'=>$p]);$row=$s->fetch();if(!is_array($row)||!in_array($row['status'],['approved','issued'],true))throw new DocumentException('transmittal_revision_ineligible');if($row['issuePurpose']!==$purpose)throw new DocumentException('transmittal_revision_purpose_mismatch');$out[]=$row;}return$out;}
    /** @return list<array<string,mixed>> */private function storedItems(string$o,string$id):array{$s=$this->pdo->prepare("SELECT LOWER(HEX(r.id)) revisionId,LOWER(HEX(r.document_id)) documentId,r.revision_code revisionCode,r.status,r.issue_purpose issuePurpose,r.audit_hash documentAuditHash,d.title,d.document_type documentType,d.discipline FROM document_transmittal_items i JOIN document_revisions r ON r.id=i.revision_id JOIN controlled_documents d ON d.id=r.document_id AND d.organisation_id=r.organisation_id WHERE i.transmittal_id=UNHEX(:id) AND r.organisation_id=UNHEX(:o) ORDER BY i.item_order");$s->execute(['id'=>$id,'o'=>$o]);return$s->fetchAll();}
    /** @return list<string> */private function roles(mixed$v):array{if(!is_array($v)||$v===[]||count($v)>30)throw new DocumentException('transmittal_recipients_required');$out=[];foreach($v as$role){$role=$this->text($role,60,'transmittal_recipient_invalid');if(preg_match('/\A[a-z][a-z0-9_]{1,59}\z/',$role)!==1)throw new DocumentException('transmittal_recipient_invalid');$out[$role]=true;}return array_keys($out);}
    /** @param array<string,mixed> $payload */private function inbox(string$o,string$p,string$role,string$id,string$code,string$title,string$sha):void{$payload=$this->json(['transmittalId'=>$id,'code'=>$code,'snapshotSha256'=>$sha,'externalDeliveryClaimed'=>false]);$this->pdo->prepare("INSERT INTO workflow_events(id,organisation_id,project_id,event_type,priority,source_module,payload) VALUES(UNHEX(:id),UNHEX(:o),UNHEX(:p),'document_transmittal_issued','medium','documents',:payload)")->execute(['id'=>Identifier::generate(),'o'=>$o,'p'=>$p,'payload'=>$payload]);$this->pdo->prepare("INSERT INTO inbox_items(id,organisation_id,project_id,assigned_role,event_type,title,detail,priority,status,payload) VALUES(UNHEX(:id),UNHEX(:o),UNHEX(:p),:role,'document_transmittal_issued',:title,:detail,'medium','open',:payload)")->execute(['id'=>Identifier::generate(),'o'=>$o,'p'=>$p,'role'=>$role,'title'=>$code.' '.$title,'detail'=>'An exact controlled-revision transmittal is available in Architex. External delivery is not claimed.','payload'=>$payload]);}
    private function project(string$o,string$p):void{$s=$this->pdo->prepare('SELECT 1 FROM projects WHERE id=UNHEX(:p) AND organisation_id=UNHEX(:o)');$s->execute(['p'=>$p,'o'=>$o]);if($s->fetchColumn()===false)throw new DocumentException('transmittal_project_not_found');}
    private function writer(string$o,string$u,string$r):void{if(!in_array($r,['owner','admin','member'],true))throw new DocumentException('transmittal_permission_denied');$this->member($o,$u);}
    private function member(string$o,string$u):void{$s=$this->pdo->prepare("SELECT 1 FROM organisation_memberships WHERE organisation_id=UNHEX(:o) AND user_id=UNHEX(:u) AND status='active'");$s->execute(['o'=>$o,'u'=>$u]);if($s->fetchColumn()===false)throw new DocumentException('transmittal_permission_denied');}
    private function id(mixed$v,string$e):string{if(!is_string($v)||preg_match('/\A[a-f0-9]{32}\z/i',$v)!==1)throw new DocumentException($e);return strtolower($v);}private function text(mixed$v,int$m,string$e):string{$v=is_string($v)?trim($v):'';if($v===''||mb_strlen($v)>$m)throw new DocumentException($e);return$v;}private function optional(mixed$v,int$m,string$e):string{$v=is_string($v)?trim($v):'';if(mb_strlen($v)>$m)throw new DocumentException($e);return$v;}private function choice(mixed$v,array$a,string$e):string{if(!is_string($v)||!in_array($v,$a,true))throw new DocumentException($e);return$v;}/** @param array<mixed> $v */private function json(array$v):string{return json_encode($v,JSON_THROW_ON_ERROR|JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);}
}
